import unittest

from text_utils import *  # noqa: F403


class Tests(unittest.TestCase):
    def test_punctuation(self):
        self.assertEqual(slugify("Hello,  World!"), "hello-world")

    def test_edges(self):
        self.assertEqual(slugify("  Tea & Cake "), "tea-cake")


